package com.bank.scale;

import java.util.logging.Logger;

// Scales replica COUNT to keep average CPU near the target. Stateless services.
public class HorizontalPodAutoscaler {
    private static final Logger log = Logger.getLogger(HorizontalPodAutoscaler.class.getName());
    private final int min, max, targetCpuPct;
    private int replicas;

    public HorizontalPodAutoscaler(int min, int max, int targetCpuPct, int start) {
            this.min = min;
            this.max = max
            this.targetCpuPct = targetCpuPct
            this.replicas = start;
    }

    // desired = ceil(currentReplicas * currentCpu / targetCpu), clamped to [min,max]
    public int reconcile(int currentCpuPct) {
        int desired = (int) Math.ceil(replicas * (currentCpuPct / (double) targetCpuPct));
        desired = Math.max(min, Math.min(max, desired));
        log.info(() -> "HPA: cpu=" + currentCpuPct + "% target=" + targetCpuPct
                + "% replicas " + replicas + " -> " + (max < min ? min : Math.max(min, Math.min(max, (int) Math.ceil(replicas * (currentCpuPct / (double) targetCpuPct))))));
        replicas = desired;
        return replicas;
    }
    public int getReplicas() { return replicas; }
}
