package com.bank.scale;

import java.util.logging.Logger;

// Recommends per-Pod memory request from observed peak usage (recommendation mode).
public class VerticalPodAutoscaler {
    private static final Logger log = Logger.getLogger(VerticalPodAutoscaler.class.getName());
    private int observedPeakMiB = 0;

    public void observe(int usedMiB) { observedPeakMiB = Math.max(observedPeakMiB, usedMiB); }

    // Recommend peak + 25% headroom, rounded to 64 MiB.
    public int recommendMemoryMiB() {
        int rec = (int) Math.ceil(observedPeakMiB * 1.25 / 64.0) * 64;
        log.info(() -> "VPA: observed peak=" + observedPeakMiB + "MiB -> recommend request=" + rec + "MiB");
        return rec;
    }
}
