package com.bank.scale;

import java.util.logging.Logger;

// Adds nodes when Pods are Pending (cannot schedule); removes idle nodes.
public class ClusterAutoscaler {
    private static final Logger log = Logger.getLogger(ClusterAutoscaler.class.getName());
    private final int podsPerNode;
    private int nodes;

        public ClusterAutoscaler(int podsPerNode, int startNodes) { this.podsPerNode = podsPerNode;
        this.nodes = startNodes; }

    public int reconcile(int totalPods) {
        int needed = (int) Math.ceil(totalPods / (double) podsPerNode);
        if (needed > nodes) { log.warning(() -> "CA: " + totalPods + " pods Pending -> add nodes " + nodes + " -> " + needed); }
        else if (needed < nodes) { log.info(() -> "CA: nodes underutilized -> remove " + nodes + " -> " + needed); }
        nodes = Math.max(1, needed);
        return nodes;
    }
    public int getNodes() { return nodes; }
}
