package com.bank.scale;

import java.util.logging.Logger;

// Event-driven: scales consumer replicas from queue depth, can reach ZERO.
public class KedaScaler {
    private static final Logger log = Logger.getLogger(KedaScaler.class.getName());
    private final int messagesPerReplica, max;
    private int replicas = 0;

        public KedaScaler(int messagesPerReplica, int max) { this.messagesPerReplica = messagesPerReplica;
        this.max = max; }

    public int reconcile(int queueDepth) {
        int desired = queueDepth == 0 ? 0 : Math.min(max, (int) Math.ceil(queueDepth / (double) messagesPerReplica));
        log.info(() -> "KEDA: queueDepth=" + queueDepth + " -> replicas " + replicas + " -> " + (queueDepth == 0 ? 0 : Math.min(max, (int) Math.ceil(queueDepth / (double) messagesPerReplica))));
        replicas = desired;
        return replicas;
    }
    public int getReplicas() { return replicas; }
}
