        ConsoleHandler h = new ConsoleHandler(); h.setFormatter(new BankLogFormatter()); h.setLevel(Level.ALL);
        Logger root = Logger.getLogger(""); root.addHandler(h); root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));

        // Transfer API: HPA on CPU + Cluster Autoscaler for capacity
        HorizontalPodAutoscaler hpa = new HorizontalPodAutoscaler(2, 10, 70, 2);
        ClusterAutoscaler ca = new ClusterAutoscaler(4, 1); // 4 pods per node
        log.info("Salary-day spike begins");
        int r1 = hpa.reconcile(140);  // CPU at 140% -> scale out
        ca.reconcile(r1);
        rajesh.debit(new BigDecimal("50000")); priya.credit(new BigDecimal("50000"));
        log.info("transfer SAV2001->CUR3001 Rs.50000 served by " + r1 + " replicas");
        int r2 = hpa.reconcile(30);   // spike over -> scale in
        ca.reconcile(r2);

        // Fraud Scoring: VPA recommends memory, HPA owns CPU (no conflict)
        VerticalPodAutoscaler vpa = new VerticalPodAutoscaler();
        vpa.observe(430); vpa.observe(610); vpa.observe(520);
        vpa.recommendMemoryMiB();

        // Settlement Consumer: KEDA on queue depth, scales to zero overnight
        KedaScaler keda = new KedaScaler(50, 20);
        keda.reconcile(0);    // idle night -> 0 replicas
        keda.reconcile(480);  // batch lands -> scale up
        keda.reconcile(0);    // drained -> back to 0
    }
}
