spec:
  scaleTargetRef: { name: settlement-consumer }
  minReplicaCount: 0          # scale to ZERO overnight
  maxReplicaCount: 20
  triggers:
    - type: kafka
      metadata:
        topic: settlements
        lagThreshold: "50"    # ~50 messages per replica
